const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v1.0/workflow_activity_histories',
  qs: {
    workflow_instance_id: 'SOME_INTEGER_VALUE',
    'filters[workflowed_object_type]': 'SOME_STRING_VALUE',
    'filters[workflowed_object_id]': 'SOME_INTEGER_VALUE',
    project_id: 'SOME_INTEGER_VALUE',
    company_id: 'SOME_INTEGER_VALUE',
    page: 'SOME_INTEGER_VALUE',
    per_page: 'SOME_INTEGER_VALUE',
    sort: 'SOME_STRING_VALUE'
  }
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/workflow_activity_histories?workflow_instance_id=SOME_INTEGER_VALUE&filters%5Bworkflowed_object_type%5D=SOME_STRING_VALUE&filters%5Bworkflowed_object_id%5D=SOME_INTEGER_VALUE&project_id=SOME_INTEGER_VALUE&company_id=SOME_INTEGER_VALUE&page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE&sort=SOME_STRING_VALUE"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

const request = require('request');

const options = {
  method: 'POST',
  url: 'https://api.procore.com/rest/v1.0/workflow_activity_histories',
  qs: {workflow_instance_id: 'SOME_INTEGER_VALUE', company_id: 'SOME_INTEGER_VALUE'},
  headers: {'content-type': 'application/json'},
  body: {
    workflow_activity_history: {
      workflow_activity_id: 12345,
      workflow_instance_id: 12345,
      workflow_user_role_id: 12345,
      performed_by_id: 12345,
      comments: 'Forwarding this for review',
      prostore_file_ids: [12334],
      attachments: ['string']
    }
  },
  json: true
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Post,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/workflow_activity_histories?workflow_instance_id=SOME_INTEGER_VALUE&company_id=SOME_INTEGER_VALUE"),
    Content = new StringContent("{\"workflow_activity_history\":{\"workflow_activity_id\":12345,\"workflow_instance_id\":12345,\"workflow_user_role_id\":12345,\"performed_by_id\":12345,\"comments\":\"Forwarding this for review\",\"prostore_file_ids\":[12334],\"attachments\":[\"string\"]}}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
